import io, contextlib
class A:
    def __str__(self):
        return 'friendly'
    def __repr__(self):
        return 'precise'
buf = io.StringIO()
with contextlib.redirect_stdout(buf):
    print(A())
assert buf.getvalue() == 'friendly\n'

class A:
    def __str__(self):
        return 'friendly'
    def __repr__(self):
        return 'precise'
assert str([A()]) == '[precise]'

class A:
    def __eq__(self, other):
        return True
assert A() == A()
assert A() == 5

class Coin:
    def __init__(self, value):
        self.value = value
    def __eq__(self, other):
        return isinstance(other, Coin) and self.value == other.value
a, b = Coin(5), Coin(5)
assert a == b
assert a is not b
